/* ------------------------------------------------------------------ */
/* Netlink / nfnetlink helpers                                          */
/* ------------------------------------------------------------------ */

#ifndef NFNL_SUBSYS_CTNETLINK
#define NFNL_SUBSYS_CTNETLINK   1
#endif

#ifndef IPCTNL_MSG_CT_GET
#define IPCTNL_MSG_CT_GET       0
#endif

/* CTA_FILTER nested attribute sub-attributes */
#ifndef CTA_FILTER
#define CTA_FILTER              17
#endif

/*
 * Bits in CTA_FILTER sub-attributes:
 * FILTER_F_IP_SRC  = (1 << 0)  -- filter on src IP
 * FILTER_F_IP_DST  = (1 << 1)  -- filter on dst IP
 */
#define FILTER_F_IP_SRC   (1U << 0)
#define FILTER_F_IP_DST   (1U << 1)

/* Maximum reply buffer */
#define RECV_BUF 65536

/* Sub-attribute types for CTA_FILTER */
#define CTA_FILTER_UNSPEC        0
#define CTA_FILTER_ORIG_FLAGS    1
#define CTA_FILTER_REPLY_FLAGS   2

/* ------------------------------------------------------------------ */
/* Minimal netlink message builder                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    uint8_t  buf[8192];
    size_t   len;
} nlmsg_t;

static void nlmsg_init(nlmsg_t *m, uint16_t nlmsg_type, uint16_t nlmsg_flags,
                       uint8_t nfgen_family, uint8_t version, uint16_t res_id)
{
    struct nlmsghdr *nlh;
    struct nfgenmsg *nfg;

    memset(m, 0, sizeof(*m));
    nlh = (struct nlmsghdr *)m->buf;
    nlh->nlmsg_type  = nlmsg_type;
    nlh->nlmsg_flags = nlmsg_flags;
    nlh->nlmsg_seq   = (uint32_t)time(NULL);
    nlh->nlmsg_pid   = (uint32_t)getpid();

    nfg = (struct nfgenmsg *)(m->buf + sizeof(struct nlmsghdr));
    nfg->nfgen_family = nfgen_family;
    nfg->version      = version;
    nfg->res_id       = htons(res_id);

    m->len = sizeof(struct nlmsghdr) + sizeof(struct nfgenmsg);
}

/* Append a raw TLV netlink attribute */
static int nla_put_raw(nlmsg_t *m, uint16_t type,
                       const void *data, uint16_t data_len)
{
    size_t nla_len = sizeof(struct nlattr) + data_len;
    size_t nla_pad = (nla_len + 3) & ~(size_t)3;
    struct nlattr nla;

    if (m->len + nla_pad > sizeof(m->buf))
        return -ENOMEM;

    nla.nla_len  = (uint16_t)nla_len;
    nla.nla_type = type;
    memcpy(m->buf + m->len, &nla, sizeof(nla));
    if (data_len)
        memcpy(m->buf + m->len + sizeof(nla), data, data_len);
    if (nla_pad > nla_len)
        memset(m->buf + m->len + nla_len, 0, nla_pad - nla_len);
    m->len += nla_pad;
    return 0;
}

static int nla_put_u32(nlmsg_t *m, uint16_t type, uint32_t val)
{
    uint32_t be = htonl(val);
    return nla_put_raw(m, type, &be, sizeof(be));
}

/* Start a nested attribute; returns offset of the nla header */
static size_t nla_nest_start(nlmsg_t *m, uint16_t type)
{
    size_t off = m->len;
    struct nlattr nla;
    nla.nla_len  = sizeof(nla);
    nla.nla_type = (uint16_t)(type | 0x8000u); /* NLA_F_NESTED */
    memcpy(m->buf + m->len, &nla, sizeof(nla));
    m->len += sizeof(nla);
    return off;
}

/* Patch the nested nla length */
static void nla_nest_end(nlmsg_t *m, size_t off)
{
    struct nlattr *nla = (struct nlattr *)(m->buf + off);
    nla->nla_len = (uint16_t)(m->len - off);
}

/* Finalise nlmsg length */
static void nlmsg_finish(nlmsg_t *m)
{
    struct nlmsghdr *nlh = (struct nlmsghdr *)m->buf;
    nlh->nlmsg_len = (uint32_t)m->len;
}

/* ------------------------------------------------------------------ */
/* Build and append a CTA_FILTER attribute                             */
/* ------------------------------------------------------------------ */

static int append_filter(nlmsg_t *m, uint32_t orig_flags, uint32_t reply_flags)
{
    size_t f_off = nla_nest_start(m, CTA_FILTER);
    nla_put_u32(m, CTA_FILTER_ORIG_FLAGS,  orig_flags);
    nla_put_u32(m, CTA_FILTER_REPLY_FLAGS, reply_flags);
    nla_nest_end(m, f_off);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send a netlink message and receive all replies                       */
/* Returns number of NFNL conntrack messages received, or -errno       */
/* ------------------------------------------------------------------ */

static int do_ct_dump(int fd, nlmsg_t *req, int verbose)
{
    struct sockaddr_nl addr;
    uint8_t rbuf[RECV_BUF];
    int     count = 0;
    ssize_t n;

    memset(&addr, 0, sizeof(addr));
    addr.nl_family = AF_NETLINK;

    nlmsg_finish(req);

    if (sendto(fd, req->buf, req->len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        return -errno;
    }

    /* Receive until NLMSG_DONE or error */
    while (1) {
        n = recv(fd, rbuf, sizeof(rbuf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            return -errno;
        }
        if (n == 0) break;

