                    uint16_t subsys =
                        (uint16_t)((nlh->nlmsg_type & 0xff00u) >> 8);
                    if (subsys == NFNL_SUBSYS_CTNETLINK) {
                        count++;
                        if (verbose)
                            printf("  [ct entry #%d, nlmsg_type=0x%04x]\n",
                                   count, nlh->nlmsg_type);
                    }
                }

                if (!(nlh->nlmsg_flags & NLM_F_MULTI))
                    return count;
                nlh = NLMSG_NEXT(nlh, remaining);
            }
        }
    }
    return count;
}

/* ------------------------------------------------------------------ */
/* Build an IPCTNL_MSG_CT_GET dump request with CTA_FILTER            */
/* ------------------------------------------------------------------ */

static void build_dump_req(nlmsg_t *m, uint32_t orig_flags,
                           uint32_t reply_flags)
